(()=>{function upgrade(){document.querySelectorAll('button:not(.reference-menu):not(.select-trigger)').forEach(button=>{if(button.querySelector('[data-lucide-button]'))return;let label=button.textContent.trim(),name=/Export|Excel.?CSV/i.test(label)?'Download':/More filters/i.test(label)?'Filter':/^Clear|^Reset/i.test(label)?'RotateCcw':/^←|Back/i.test(label)?'ArrowLeft':/^View/i.test(label)?'ArrowUpRight':/^×$/.test(label)?'X':/^↻$/.test(label)?'RotateCcw':/^Bar$/.test(label)?'ChartBar':/^Column$/.test(label)?'ChartColumn':/^Pie$/.test(label)?'ChartPie':/^Line$/.test(label)?'ChartLine':/^Area$/.test(label)?'ChartArea':/Chart/i.test(label)&&!label.includes('selection')?'ChartColumn':null;if(!name)return;button.querySelectorAll('svg').forEach(node=>node.remove());Array.from(button.childNodes).filter(node=>node.nodeType===3).forEach(node=>node.textContent=node.textContent.replace(/[▥▦↓↗←↻▽×]/g,'').trim());let holder=document.createElement('span');holder.className='lucide-button-icon';holder.setAttribute('data-lucide-button',name);holder.innerHTML=dashboardIcon(name);button.insertBefore(holder,button.firstChild);if(!button.textContent.trim()&&!button.getAttribute('aria-label'))button.setAttribute('aria-label',name)});document.querySelectorAll('.metric-icon').forEach((node,index)=>{if(node.querySelector('.lucide-ui'))return;node.innerHTML=dashboardIcon(['Banknote','Receipt','Users','TestTube','Package','CalendarClock','CircleX'][index%7])});document.querySelectorAll('#panelTabs button').forEach(button=>{if(button.querySelector('.lucide-ui'))return;let label=button.textContent,name=label.includes('Canonical')?'Layers':label.includes('Component')?'FlaskConical':'ClipboardList';button.querySelectorAll('svg').forEach(node=>node.remove());let span=document.createElement('span');span.innerHTML=dashboardIcon(name);button.insertBefore(span.firstChild,button.firstChild)})}let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;upgrade()})}).observe(document.body,{childList:true,subtree:true});upgrade()})();


