(()=>{function alignClose(){document.querySelectorAll('.rev-chart').forEach(panel=>{let row=panel.querySelector('.revenue-chart-toolbar');if(!row)return;let button=panel.querySelector('.rev-close');if(!button){let id=panel.id.replace('chart-','');button=document.createElement('button');button.type='button';button.className='rev-close';button.setAttribute('aria-label','Close chart');button.innerHTML=dashboardIcon('X');button.onclick=()=>toggleRevenueChart(id)}button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)});document.querySelectorAll('.specialty-chart').forEach(panel=>{let row=panel.querySelector('.specialty-chart-controls');if(!row)return;let button=panel.querySelector('.rev-close');if(!button){let id=panel.id.replace('specialChart-','');button=document.createElement('button');button.type='button';button.className='rev-close';button.setAttribute('aria-label','Close chart');button.innerHTML=dashboardIcon('X');button.onclick=()=>toggleSpecialChart(id)}button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)});let panel=document.getElementById('reportInlineChart');if(panel){let row=panel.querySelector('.tp-chart-types'),button=panel.querySelector('.tests-chart-close');if(row&&button){button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)}}let branch=document.getElementById('branchChartView');if(branch){let row=branch.querySelector('.branch-chart-controls'),button=branch.querySelector('.branch-chart-close');if(row&&button){button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)}}}let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;alignClose()})}).observe(document.body,{childList:true,subtree:true});alignClose()})();

(()=>{const ids=['centre','clientType','client','moreCity','moreZone','moreCategory','moreDoctor','moreRep'],buttons=new Map();let active=null;function options(id){return Array.from(document.getElementById(id).options).filter(option=>option.value!=='All'&&!option.disabled).map(option=>option.value)}function chosen(id){return window.testsMultiFilters[id]||new Set(options(id))}function sync(){buttons.forEach((button,id)=>{let values=options(id),set=chosen(id),label=set.size===values.length?'All':set.size===0?'None':set.size===1?[...set][0]:set.size+' selected';button.textContent=label;button.setAttribute('title',set.size?[...set].join(', '):'No options selected');button.setAttribute('aria-label',(document.getElementById(id).getAttribute('aria-label')||({centre:'Centre',clientType:'Client Type',client:'Client'}[id])||'Filter')+': '+label)});if(active){let set=chosen(active.id),values=options(active.id);active.all.textContent=(set.size===values.length?'Deselect all':'Select all')+' ('+values.length+')';active.menu.querySelectorAll('input[type="checkbox"]').forEach(input=>input.checked=set.has(input.value));active.footer.textContent=set.size+' of '+values.length+' selected'}}function close(focus=false){if(!active)return;let prior=active;active=null;prior.menu.remove();prior.button.setAttribute('aria-expanded','false');if(focus)prior.button.focus()}function update(id,set){window.testsMultiFilters[id]=set;if(typeof reportState!=='undefined')Object.values(reportState).forEach(state=>state.page=1);refreshHome();sync()}function open(id,button){close();const menu=document.createElement('div');menu.className='checkbox-filter-menu';menu.id='checkbox-filter-'+id;menu.setAttribute('role','dialog');menu.setAttribute('aria-label',document.getElementById(id).getAttribute('aria-label')||'Filter options');const all=document.createElement('button');all.type='button';all.className='checkbox-filter-all';all.onclick=()=>{let values=options(id);update(id,chosen(id).size===values.length?new Set():new Set(values))};const list=document.createElement('div');list.className='checkbox-filter-options';options(id).forEach(value=>{let label=document.createElement('label');label.className='checkbox-filter-option';let input=document.createElement('input');input.type='checkbox';input.value=value;input.checked=chosen(id).has(value);input.onchange=()=>{let selected=new Set(chosen(id));input.checked?selected.add(value):selected.delete(value);update(id,selected)};let text=document.createElement('span');text.textContent=value;label.append(input,text);list.appendChild(label)});const footer=document.createElement('div');footer.className='checkbox-filter-footer';menu.append(all,list,footer);document.body.appendChild(menu);active={id,button,menu,all,footer};sync();button.setAttribute('aria-expanded','true');button.setAttribute('aria-controls',menu.id);let rect=button.closest('.tp-more-filter')?.getBoundingClientRect()||button.getBoundingClientRect(),width=Math.min(350,Math.max(220,rect.width));menu.style.width=width+'px';menu.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';let remaining=innerHeight-rect.bottom-20;if(remaining>170){menu.style.top=(rect.bottom+8)+'px';list.style.maxHeight=Math.min(290,remaining-95)+'px'}else{list.style.maxHeight=Math.max(90,Math.min(290,rect.top-110))+'px';menu.style.top=Math.max(12,rect.top-8-menu.offsetHeight)+'px'}all.focus()}
ids.forEach(id=>{let select=document.getElementById(id),wrap=select.closest('.styled-select');if(!wrap)return;let button=wrap.querySelector('.select-trigger');button.classList.add('multi-select-trigger');button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.onclick=event=>{event.preventDefault();active?.id===id?close(true):open(id,button)};button.onkeydown=event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();open(id,button)}};buttons.set(id,button)});document.addEventListener('pointerdown',event=>{if(active&&!active.menu.contains(event.target)&&!active.button.contains(event.target))close()});document.addEventListener('keydown',event=>{if(active&&event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true)}});document.addEventListener('scroll',event=>{if(active&&!active.menu.contains(event.target))close()},true);window.addEventListener('resize',()=>close());const previousRefresh=refreshHome;refreshHome=function(){let result=previousRefresh.apply(this,arguments);sync();return result};const previousReset=resetAll;resetAll=function(){close();let result=previousReset.apply(this,arguments);sync();return result};sync();})();
